import{_ as a,o as e,c as r,ag as d}from"./chunks/framework.CtWPcAmt.js";const g=JSON.parse('{"title":"第 16 章：一个可演进的 Harness 架构","description":"入口、上下文、执行、安全、验证、反馈六层架构；每层的职责与组件；产出最小 Harness 设计表。","frontmatter":{"title":"第 16 章：一个可演进的 Harness 架构","description":"入口、上下文、执行、安全、验证、反馈六层架构；每层的职责与组件；产出最小 Harness 设计表。","layout":"doc","lastUpdated":true},"headers":[],"relativePath":"guide/16-harness-architecture.md","filePath":"guide/16-harness-architecture.md","lastUpdated":null}'),o={name:"guide/16-harness-architecture.md"};function l(i,t,s,n,h,c){return e(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="第-16-章-一个可演进的-harness-架构" tabindex="-1">第 16 章：一个可演进的 Harness 架构 <a class="header-anchor" href="#第-16-章-一个可演进的-harness-架构" aria-label="Permalink to &quot;第 16 章：一个可演进的 Harness 架构&quot;">​</a></h1><h2 id="本章解决什么问题" tabindex="-1">本章解决什么问题 <a class="header-anchor" href="#本章解决什么问题" aria-label="Permalink to &quot;本章解决什么问题&quot;">​</a></h2><p>第 15 章让你看见了 Harness 的样子，本章给你一套<strong>可以照着搭的结构</strong>：六层架构。每一层做什么、放什么组件、怎么和相邻层协作，一次讲清。产出：<strong>最小 Harness 设计表</strong>——你可以直接照着它搭一个能跑的最小版本，以后再逐步演进。</p><h2 id="从一个真实场景开始" tabindex="-1">从一个真实场景开始 <a class="header-anchor" href="#从一个真实场景开始" aria-label="Permalink to &quot;从一个真实场景开始&quot;">​</a></h2><p>本书项目从「几个 Markdown 文件」长成了「20 多个章节 + 30 多个素材文件 + 七款产品数据」的复杂工程。能撑住，不是靠某一个模型，而是靠一层层「制度」：</p><ul><li>想写新章节？→ 有章节模板和编辑规范（入口层）；</li><li>写之前要知道背景？→ 有 <code>docs/00-06</code> 定位与规范（上下文层）；</li><li>谁来写、怎么验收？→ 有写作流程与内容清单（执行+验证层）；</li><li>价格、版本会变？→ 有 <code>docs/07</code> 集中维护（反馈/易变信息层）。</li></ul><p><strong>这套结构不是一次设计出来的，是随着「踩坑 → 补层」长出来的。</strong> 本章给你的是它的通用骨架。</p><h2 id="先说结论" tabindex="-1">先说结论 <a class="header-anchor" href="#先说结论" aria-label="Permalink to &quot;先说结论&quot;">​</a></h2><ol><li><strong>六层架构</strong>：入口 → 上下文 → 执行 → 安全 → 验证 → 反馈。每层解决一类问题，缺一层就会出现对应症状；</li><li><strong>分层原则</strong>：每层只做一件事，层间通过文件/接口传信息，不互相塞内容；</li><li><strong>演进而不是一步到位</strong>：先搭「入口 + 上下文 + 执行」跑通最小闭环，再逐步加安全、验证、反馈；</li><li><strong>可演进的关键</strong>：每层组件都是「文件/配置」，改一层不动其他层；</li><li><strong>最小版本就够用</strong>：一个人的 Harness 不需要企业级复杂度，能闭环、能查、能改即可。</li></ol><h2 id="必要概念" tabindex="-1">必要概念 <a class="header-anchor" href="#必要概念" aria-label="Permalink to &quot;必要概念&quot;">​</a></h2><ul><li><strong>分层架构（Layered architecture）</strong>：把系统按职责分成若干层，每层只依赖相邻层。白话解释：公司分部门，市场部不直接管财务，但信息能通过流程传递。</li><li><strong>入口层（Entry）</strong>：接收任务意图的地方：任务卡、会话、定时触发。</li><li><strong>执行层（Execution）</strong>：Agent 实际干活的地方：模型 + 工具 + Skill。</li><li><strong>安全层（Security）</strong>：权限、隔离、审批、撤销。</li><li><strong>验证层（Verification）</strong>：测试、审查、验收。</li><li><strong>反馈层（Feedback）</strong>：日志、复盘、知识沉淀。</li></ul><h2 id="六层架构设计表-最小版" tabindex="-1">六层架构设计表（最小版） <a class="header-anchor" href="#六层架构设计表-最小版" aria-label="Permalink to &quot;六层架构设计表（最小版）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>职责</th><th>最小组件</th><th>缺了会怎样</th></tr></thead><tbody><tr><td><strong>入口层</strong></td><td>收任务、定意图</td><td>任务卡模板、任务队列</td><td>任务描述不清，第一步就歪</td></tr><tr><td><strong>上下文层</strong></td><td>提供视野</td><td>CONTEXT.md、材料清单、规则文件</td><td>Agent 猜、误判、编造</td></tr><tr><td><strong>执行层</strong></td><td>干活</td><td>Agent 产品、Skill、脚本</td><td>无法落地</td></tr><tr><td><strong>安全层</strong></td><td>控边界</td><td>权限卡、审批规则、备份</td><td>越权、误删、泄漏</td></tr><tr><td><strong>验证层</strong></td><td>保证质量</td><td>验收清单、自检要求、哈希校验</td><td>错误被当成正确</td></tr><tr><td><strong>反馈层</strong></td><td>沉淀改进</td><td>复盘记录、易变信息表、模板迭代</td><td>同样的问题反复犯</td></tr></tbody></table><h2 id="跟着做-用设计表搭你的最小-harness" tabindex="-1">跟着做：用设计表搭你的最小 Harness <a class="header-anchor" href="#跟着做-用设计表搭你的最小-harness" aria-label="Permalink to &quot;跟着做：用设计表搭你的最小 Harness&quot;">​</a></h2><h3 id="第一步-从「执行层」开始确认" tabindex="-1">第一步：从「执行层」开始确认 <a class="header-anchor" href="#第一步-从「执行层」开始确认" aria-label="Permalink to &quot;第一步：从「执行层」开始确认&quot;">​</a></h3><p>你已有 Agent 产品（第 6 章）和 Skill（第 13 章）→ 执行层就绪。</p><h3 id="第二步-补齐「入口-上下文」" tabindex="-1">第二步：补齐「入口 + 上下文」 <a class="header-anchor" href="#第二步-补齐「入口-上下文」" aria-label="Permalink to &quot;第二步：补齐「入口 + 上下文」&quot;">​</a></h3><ul><li>入口：把你的任务卡模板放在固定位置（如 <code>tasks/</code> 目录）；</li><li>上下文：建立 CONTEXT.md（第 11 章已建过，确认存在）。</li></ul><h3 id="第三步-加「安全层」最简版" tabindex="-1">第三步：加「安全层」最简版 <a class="header-anchor" href="#第三步-加「安全层」最简版" aria-label="Permalink to &quot;第三步：加「安全层」最简版&quot;">​</a></h3><ul><li>权限卡（第 8 章）放项目根目录；</li><li>加一条硬规则：「没有人工确认，不执行删除/发送/发布」（第 14 章全局安全底线）。</li></ul><h3 id="第四步-加「验证层」最简版" tabindex="-1">第四步：加「验证层」最简版 <a class="header-anchor" href="#第四步-加「验证层」最简版" aria-label="Permalink to &quot;第四步：加「验证层」最简版&quot;">​</a></h3><ul><li>验收清单（第 10 章）放项目根目录；</li><li>每个任务卡末尾必须写「验收标准」（第 7 章已有）。</li></ul><h3 id="第五步-加「反馈层」最简版" tabindex="-1">第五步：加「反馈层」最简版 <a class="header-anchor" href="#第五步-加「反馈层」最简版" aria-label="Permalink to &quot;第五步：加「反馈层」最简版&quot;">​</a></h3><ul><li>每次任务后在 <code>reviews/</code> 记一条复盘（三行：做得好/问题/下次改什么）；</li><li>易变信息（价格、版本）集中到一张表并标核验日期。</li></ul><h3 id="第六步-画你的设计表" tabindex="-1">第六步：画你的设计表 <a class="header-anchor" href="#第六步-画你的设计表" aria-label="Permalink to &quot;第六步：画你的设计表&quot;">​</a></h3><p>把上面的组件填进「六层架构设计表」，标出哪层已就绪、哪层还是空的。</p><h2 id="一个完整示例-本书项目的六层落地" tabindex="-1">一个完整示例（本书项目的六层落地） <a class="header-anchor" href="#一个完整示例-本书项目的六层落地" aria-label="Permalink to &quot;一个完整示例（本书项目的六层落地）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>本书项目对应</th></tr></thead><tbody><tr><td>入口</td><td><code>templates/chapter-template.md</code>、内容清单 <code>docs/04</code></td></tr><tr><td>上下文</td><td><code>docs/00-06</code>（定位/目录/规范）、材料在 <code>research/</code>、<code>chapters/</code></td></tr><tr><td>执行</td><td>桌面 Agent（第 6 章选型）+ 界面讲解/产品页写作流程</td></tr><tr><td>安全</td><td>截图脱敏规则、价格核验规则、Claude 封号只写个案（<code>docs/03</code>）</td></tr><tr><td>验证</td><td>章节模板的「常见错误/练习/成果」结构、链接校验、内容清单打勾</td></tr><tr><td>反馈</td><td><code>docs/04</code> 迭代、<code>research/</code> 各 run-record、<code>docs/07</code> 易变信息表</td></tr></tbody></table><p><strong>关键点：这套架构的每个组件都是普通 Markdown 文件</strong>——任何一层都可以独立修改、替换、升级，不影响其他层。这就是「可演进」。</p><h2 id="常见错误与恢复方法" tabindex="-1">常见错误与恢复方法 <a class="header-anchor" href="#常见错误与恢复方法" aria-label="Permalink to &quot;常见错误与恢复方法&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>可能原因</th><th>怎样修正</th></tr></thead><tbody><tr><td>一开始就想搭完整版</td><td>违背「最小可用」</td><td>先六层各一件最小组件，跑通再升级</td></tr><tr><td>层与层互相塞内容</td><td>违背分层原则</td><td>文件只放本层职责内容，层间靠引用</td></tr><tr><td>只有入口+执行，老翻车</td><td>缺验证/安全</td><td>优先补验证层（错误最贵）</td></tr><tr><td>组件散落各处找不到</td><td>没有目录约定</td><td>固定目录结构（docs/、tasks/、reviews/）</td></tr><tr><td>架构文档写得很美但没人用</td><td>组件没接入流程</td><td>把「用架构」写进任务卡模板，强制引用</td></tr></tbody></table><h2 id="安全提醒" tabindex="-1">安全提醒 <a class="header-anchor" href="#安全提醒" aria-label="Permalink to &quot;安全提醒&quot;">​</a></h2><ul><li>安全层组件（权限卡、审批规则）一旦定义，<strong>不要在任务中随意绕过</strong>——绕过一次，杠杆反向放大；</li><li>反馈层里记录的复盘、易变信息，注意脱敏后再存；</li><li>Harness 组件是文件，也是「制度」：确保它们与你的组织政策一致。</li></ul><h2 id="本章练习" tabindex="-1">本章练习 <a class="header-anchor" href="#本章练习" aria-label="Permalink to &quot;本章练习&quot;">​</a></h2><p>40 分钟：用六层设计表搭你的最小 Harness（每层一件最小组件），画设计表并标出「已就绪/空缺」层。空缺层按优先级补（建议顺序：验证 &gt; 安全 &gt; 反馈 &gt; 上下文 &gt; 入口）。</p><h2 id="你应该带走的成果" tabindex="-1">你应该带走的成果 <a class="header-anchor" href="#你应该带走的成果" aria-label="Permalink to &quot;你应该带走的成果&quot;">​</a></h2><ul><li><strong>最小 Harness 设计表</strong>（六层 × 组件 × 就绪状态），可以直接照着实施。</li></ul><h2 id="本章小结" tabindex="-1">本章小结 <a class="header-anchor" href="#本章小结" aria-label="Permalink to &quot;本章小结&quot;">​</a></h2><ol><li>六层架构：入口、上下文、执行、安全、验证、反馈；</li><li>分层原则：每层一件事，层间靠文件引用协作；</li><li>先最小闭环，再逐步演进；</li><li>组件都是普通文件，改一层不动其他层；</li><li>下一章回答「要不要多 Agent」（第 17 章）。</li></ol>',39)])])}const b=a(o,[["render",l]]);export{g as __pageData,b as default};
